{
  "summary": "On 18 March 2025 payments-api-03 emitted ~40 PAYAPI-W0310 logs per second while fraud-scorer-01 showed ~45% CPU usage but ~30% throttled periods, caused by an oversubscribed worker count.",
  "likely_cause": "WEB_CONCURRENCY was unset, causing 16 gunicorn workers to exceed the pod's CPU limit and trigger CFS throttling.",
  "confidence": "high",
  "claims": [
    {
      "text": "payments-api-03 logged about 40 PAYAPI-W0310 messages per second",
      "evidence_ids": ["RB-002#3"],
      "quote": "payments-api-03.prod.internal was logging W0310 at about 40 per second"
    },
    {
      "text": "fraud-scorer-01 used about 45% of its CPU limit on average and had ~30% throttled periods",
      "evidence_ids": ["RB-002#3", "INC-0024#1"],
      "quote": "fraud-scorer-01... showed 30% throttled periods and only 45% average CPU"
    },
    {
      "text": "The throttling was caused by 16 gunicorn workers started because WEB_CONCURRENCY was unset, exceeding the CPU limit",
      "evidence_ids": ["INC-0024#2"],
      "quote": "WEB_CONCURRENCY was unset... started a worker for each... pod's CPU limit is smaller than 16 cores"
    }
  ],
  "next_checks": [
    "Confirm the current WEB_CONCURRENCY setting in the fraud-scorer Deployment",
    "Monitor container_cpu_cfs_throttled_periods_total vs total periods for fraud-scorer",
    "Check GOMAXPROCS value inside the payments-api pod"
  ]
}
